import{_ as r,l as c,o as a,c as i,v as o,p as l,x as d,d as s,i as n,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"ELF 格式","description":"","frontmatter":{"title":"ELF 格式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/elf-format.md","filePath":"cs/elf-format.md","lastUpdated":1789023840000}'),p={name:"cs/elf-format.md"};function _(h,e,f,m,A,u){const t=c("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="elf-格式" tabindex="-1">ELF 格式 <a class="header-anchor" href="#elf-格式" aria-label="Permalink to &quot;ELF 格式&quot;">​</a></h1><div class="epigraph"><p>ELF 是 Unix 上可重定位、可执行与共享对象的容器：ELF 头、程序头、节头、符号与重定位表按约定排布。</p><footer>—— 据 System V ABI 与 ELF 规范；Levine；主干目标文件讨论整理</footer></div><p>上一课<a href="/cs/icf-identical-code-folding">ICF</a> 在节上操作。缺口是<strong>文件格式本身</strong>：<code>Elf64_Ehdr</code>、<code>Phdr</code>、<code>Shdr</code>、节名 <code>.text</code>。本课钉结构，加载下一课。不把 PE/Mach-O 写完，只点名对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>汇编器/编译器写 <code>ET_REL</code>；链接器写 <code>ET_EXEC</code>/<code>ET_DYN</code>。谁看程序头：内核与 <code>ld.so</code>。谁看节头：链接器、调试器、<code>objdump</code>。缺口是<strong>两套表</strong>，不是 ICF 算法。</p><p>符号表：<code>.symtab</code> 完整，<code>.dynsym</code> 动态子集。字符串表伴随。</p><h3 id="节头可被-strip" tabindex="-1">节头可被 strip <a class="header-anchor" href="#节头可被-strip" aria-label="Permalink to &quot;节头可被 strip&quot;">​</a></h3><p>加载不依赖节头。strip 后调试困难，程序仍可跑。不要认为「没有节就不能执行」。</p><p><span class="marginnote">ELF 规范。<code>readelf -a</code>。本课 64 位小端为例。不进 Windows PE 细节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读 <code>e_ident</code> 魔数、类、端序。跟 <code>e_phoff</code>/<code>e_shoff</code>。解析动态节 <code>DT_*</code>。工具：<code>readelf</code>、<code>objdump -d</code>。</p>',11)),(a(),l(E,null,{default:d(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EHDR%5B%22ELF%20%E5%A4%B4%22%5D%20--%3E%20PHDR%5B%22%E7%A8%8B%E5%BA%8F%E5%A4%B4%20%E2%86%92%20%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20EHDR%20--%3E%20SHDR%5B%22%E8%8A%82%E5%A4%B4%20%E2%86%92%20%E9%93%BE%E6%8E%A5%2F%E8%B0%83%E8%AF%95%22%5D%0A%20%20SHDR%20--%3E%20SYM%5B%22%E7%AC%A6%E5%8F%B7%20%2F%20%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与链接脚本：脚本输出的节最终填进这些表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对齐：<code>p_align</code>。INTERP：<code>PT_INTERP</code> 指向动态加载器路径。没有 INTERP 的静态可执行直接进内核入口。</p><p>不要手改 ELF 当「优化」而不懂校验。构建系统应调链接器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核 <code>load_elf_binary</code> 全文。后课默认：Unix 工具链目标是 ELF。下一课 ELF 加载：内核如何 <code>mmap</code> 段。</p><p>也不把 ELF 当 DWARF 的别名（DWARF 住在 ELF 节里）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ELF：头 + 程序头（加载）+ 节头（链接/调试）。</li><li>REL/EXEC/DYN 三种。</li><li>动态信息在 <code>PT_DYNAMIC</code>。</li><li>出处：ELF / SysV ABI；Levine。</li></ul>',9))])}const T=r(p,[["render",_]]);export{D as __pageData,T as default};
